import { CHARACTER_KEYS, ENEMY_KEYS } from '../Keys.js';

/** @typedef {import('../Keys.js').CharacterKey} CharacterKey */
/** @typedef {import('../Keys.js').EnemyKey} EnemyKey */
/** @typedef {import('./AttackTimingConstants.js').DodgeTiming} DodgeTiming */
/** @typedef {import('./AttackTimingConstants.js').CounterTiming} CounterTiming */

/**
 * Basic-attack animation timing for one enemy or boss, in frames (= battle ticks). Generated by
 * Suikoden-Bizhawk-HUD's scripts/AttackTimingWalker.py from the monster's animation scripts
 * (outputs/AttackTimingsClean.json; path fields from scripts/DerivePathTimings.py); Zombie
 * Dragon's hits and the Elite Soldier / Soldier Ant miss, counter, cover and kill paths were
 * live-verified.
 *
 * Frame convention: t0 = the tick the attack executor starts the attack script (the same tick
 * as the hit and crit rolls). Each tick runs the turn coroutine first (turn rolls, dispatch,
 * damage rolls), then the animation pass. A busy bit that clears "at" frame F clears in F's
 * animation pass, so turn rolls and enemy target checks first see that combatant free at F + 1.
 *
 * @typedef {Object} EnemyAttackTiming
 * @property {string} name - Name as stored in the ROM's monster record.
 * @property {number | null} damage - t0 -> the damage roll (calc_damage's rand()): the frame
 *   after the attack script's impact, or the native handler's own hit (Neclord, Banshee, Crystal
 *   Core: calc_rune_element_attack_damage / calc_damage against every living party member).
 *   null = untimed (see blocked).
 * @property {number | null} free - t0 -> the frame the attacker's busy bit clears: the attack
 *   script's own clear if it has one (commanders, Shadow / Shadow Man, handler attackers),
 *   otherwise the return-to-position script's clear. null = unknown (see blocked).
 * @property {number} reaction - The damage roll -> the frame the TARGET's busy bit 8 clears
 *   (this enemy's reaction script, played on the character it hits; enemies never crit).
 *   Meaningless when targetBusy is false.
 * @property {Partial<Record<CharacterKey, number>>} [reactionExceptions] - Characters whose
 *   reaction differs from `reaction` (Shadow / Shadow Man only). Look up
 *   reactionExceptions?.[character] ?? reaction.
 * @property {boolean} targetBusy - Whether the attack script marks its target busy at t0. false
 *   for commanders (Queen Ant, Beast Commander: allies do the hitting) and handler attackers;
 *   for those, `reaction` doesn't apply.
 * @property {number[]} [scriptRand] - t0 -> frames with an animation-time rand() call.
 * @property {string} [blocked] - Why this entry is incomplete (a native handler the walker
 *   doesn't model); the null fields above are unknown, not zero.
 * @property {number | null} dodgePoint - t0 -> the frame this attacker's miss / counter point is
 *   set (effect flag 0x1). A dodge or counter against it starts the frame after. null = unknown.
 * @property {number | null} recover - t0 -> the frame its recover script (slot 4) starts;
 *   free - recover = its recovery length (negative when the attack script clears busy itself).
 * @property {DodgeTiming | null} dodge - As the TARGET of a missed attack (see
 *   AttackTimingConstants.js). null = unknown.
 * @property {CounterTiming} [counter] - As a RETALIATOR; omitted for anyone who can't counter
 *   (no species flag 0x2).
 * @property {number} [missFree] - Replaces `free` when this attacker misses (Siren only).
 * @property {number | null} death - Extra busy frames when this enemy is killed: its death
 *   script (table slot 7) runs once its hit reaction ends. null = unknown.
 *
 * Miss / counter / cover / kill timing: the formulas are in AttackTimingConstants.js.
 */

